private final PasswordEncoder passwordEncoder = new BCryptPasswordEncoder();

public Boolean login(UserRegisterRequestDto dto) {
    User user = userRepository.findByUsername(dto.getUsername()).orElseThrow();
    String reEncoded = passwordEncoder.encode(dto.getPassword());
    return reEncoded.equals(user.getPassword());
}

public Boolean login(UserRegisterRequestDto registerRequestDto) {
    Optional<User> userOptional =
            userRepository.findByUsername(registerRequestDto.getUsername());
    User user = userOptional.get();
    String encodedPassword = user.getPassword();
    return passwordEncoder.matches(
            registerRequestDto.getPassword(),
            encodedPassword
    );
}

public UserRegisterResponseDto register(UserRegisterRequestDto dto) {
    User user = new User();
    user.setUsername(dto.getUsername());
    user.setPassword(passwordEncoder.encode(dto.getPassword()));
    user.setEnabled(true);
    userRepository.save(user);

    UserRegisterResponseDto response = new UserRegisterResponseDto();
    response.setUsername(user.getUsername());
    response.setMessage("User saved Successfully");
    return response;
}
